import React from 'react';
import Icon from '../../../components/AppIcon';

const ContactMethods = ({ data }) => {
  const contactMethods = data?.list || [
    {
      id: 1,
      icon: "Mail",
      title: "Email Us",
      description: "For detailed inquiries, partnership proposals, or general questions",
      contact: "hello@lucopportunities.com",
      action: "Send Email",
      link: "mailto:hello@lucopportunities.com",
      color: "var(--color-brand-blue)"
    },
    {
      id: 2,
      icon: "Phone",
      title: "Call Us",
      description: "Speak directly with our support team during business hours",
      contact: "+1 (555) 123-4567",
      action: "Call Now",
      link: "tel:+15551234567",
      color: "var(--color-success)"
    }
  ];

  const socialLinks = data?.social?.links || [
    { icon: "Facebook", label: "Facebook", url: "https://facebook.com/lucopportunities", followers: "25K" },
    { icon: "Twitter", label: "Twitter", url: "https://twitter.com/lucopportunities", followers: "18K" }
  ];

  return (
    <section className="py-12 md:py-16 lg:py-20 bg-[var(--color-background)]">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-8 md:mb-12 lg:mb-16">
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
            {data?.title || "Multiple Ways to Connect"}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-2xl mx-auto">
            {data?.description || "Choose the communication channel that works best for you."}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8 mb-12 md:mb-16 lg:mb-20">
          {contactMethods?.map((method, index) => (
            <div
              key={method?.id || index}
              className="bg-[var(--color-card)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300 border border-[var(--color-border)]"
            >
              <div className="flex items-start gap-4 md:gap-6">
                <div
                  className="w-12 h-12 md:w-14 md:h-14 lg:w-16 lg:h-16 rounded-xl flex items-center justify-center flex-shrink-0"
                  style={{ backgroundColor: `${method?.color}15` }}
                >
                  <Icon name={method?.icon} size={24} color={method?.color} className="md:w-7 md:h-7 lg:w-8 lg:h-8" />
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-2" style={{ fontFamily: 'var(--font-headline)' }}>
                    {method?.title}
                  </h3>
                  <p className="text-sm md:text-base text-[var(--color-muted-foreground)] mb-3 md:mb-4">
                    {method?.description}
                  </p>
                  <p className="text-sm md:text-base font-medium text-[var(--color-foreground)] mb-4 break-words">
                    {method?.contact}
                  </p>
                  <a
                    href={method?.link}
                    className="inline-flex items-center gap-2 text-sm md:text-base font-semibold transition-colors duration-300 hover:underline"
                    style={{ color: method?.color, fontFamily: 'var(--font-cta)' }}
                  >
                    {method?.action}
                    <Icon name="ArrowRight" size={16} />
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-[var(--color-card)] rounded-2xl p-6 md:p-8 lg:p-10 shadow-[var(--shadow-card)] border border-[var(--color-border)]">
          <div className="text-center mb-6 md:mb-8">
            <h3 className="text-xl md:text-2xl lg:text-3xl font-bold text-[var(--color-primary)] mb-3 md:mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
              {data?.social?.title || "Follow Our Journey"}
            </h3>
            <p className="text-sm md:text-base text-[var(--color-muted-foreground)]">
              {data?.social?.description || "Stay updated with daily opportunity alerts."}
            </p>
          </div>
          <div className="flex flex-wrap justify-center gap-4 md:gap-6">
            {socialLinks?.map((social) => (
              <a
                key={social?.label}
                href={social?.url}
                target="_blank"
                rel="noopener noreferrer"
                className="flex flex-col items-center gap-2 p-4 md:p-6 rounded-xl bg-[var(--color-muted)] hover:bg-[var(--color-primary)] hover:text-white transition-all duration-300 group min-w-[100px] md:min-w-[120px]"
              >
                <Icon name={social?.icon} size={24} className="md:w-7 md:h-7 group-hover:scale-110 transition-transform duration-300" />
                <span className="text-xs md:text-sm font-medium">{social?.label}</span>
                <span className="text-xs opacity-70">{social?.followers}</span>
              </a>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default ContactMethods;