import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const WhatsAppSection = ({ data }) => {
    const [totalLikes, setTotalLikes] = useState('...');

    useEffect(() => {
        let isMounted = true;

        const fetchStats = async () => {
            try {
                const count = await supabaseService.getTotalLikesCount();
                if (isMounted) {
                    console.log("Verified Live Likes Fetched:", count);
                    setTotalLikes(count.toLocaleString() + '+');
                }
            } catch (e) {
                console.error("Error fetching stats:", e);
                if (isMounted) setTotalLikes("500+"); // Fallback
            }
        };

        fetchStats();

        // Valid subscription
        const channel = supabaseService.subscribeToTable('opportunities', () => {
            fetchStats();
        });

        return () => {
            isMounted = false;
            supabaseService.unsubscribe(channel);
        };
    }, []);

    const handleWhatsAppClick = () => {
        window.open(data?.link || 'https://whatsapp.com/channel/0029VaIrwmaB4hdVFlMVPg3V', '_blank');
    };

    const stats = [
        { icon: "Bell", value: "24/7", label: "Instant Alerts" },
        { icon: "Heart", value: totalLikes, label: "Loves Received" },
        { icon: "Award", value: "98%", label: "Satisfaction Rate" },
        { icon: "Globe", value: "50+", label: "Countries" }
    ];

    return (
    <section className="py-24 md:py-32 bg-slate-900 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full bg-emerald-500/5 blur-[150px] rounded-full" />

      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 relative z-10">
        <div className="flex flex-col lg:flex-row items-center gap-16 lg:gap-24">
          <div className="flex-1 text-center lg:text-left">
            <div className="inline-flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 rounded-full mb-8 backdrop-blur-md">
              <Icon name="Users" size={20} className="text-secondary" />
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-white">{data?.memberCount || "15,000+ Active Members"}</span>
            </div>
            
            <h2 className="text-4xl md:text-6xl lg:text-7xl font-black text-white mb-8 tracking-tighter italic leading-[0.9]">
              {data?.title || "Join Our\nGlobal Network"}
            </h2>
            
            <p className="text-xl text-slate-400 mb-12 font-medium leading-relaxed max-w-2xl mx-auto lg:mx-0">
              {data?.description || "Get instant opportunity alerts, connect with elite peers, and receive personalized guidance from our international community mentors."}
            </p>
            
            <div className="flex flex-col sm:flex-row gap-6 justify-center lg:justify-start">
              <Button
                variant="default"
                size="xl"
                iconName="MessageCircle"
                iconPosition="left"
                onClick={handleWhatsAppClick}
                className="bg-emerald-500 text-slate-950 hover:bg-white hover:text-slate-950 font-black italic py-6 px-12 rounded-2xl shadow-2xl transition-all duration-300"
              >
                Join Global Channel
              </Button>
            </div>
          </div>

          <div className="flex-1 grid grid-cols-2 gap-6 md:gap-8 w-full max-w-lg">
            {stats.map((stat, idx) => (
              <div key={idx} className="group relative bg-white/5 backdrop-blur-3xl rounded-[2.5rem] p-8 md:p-10 border border-white/5 hover:border-emerald-500/30 transition-all duration-700 shadow-2xl">
                <div className="w-16 h-16 rounded-2xl bg-white/5 flex items-center justify-center mb-8 group-hover:scale-110 group-hover:rotate-6 transition-all duration-500 border border-white/10">
                  <Icon name={stat.icon} size={28} className="text-emerald-500" />
                </div>
                <div className="text-left">
                  <div className="text-3xl md:text-4xl font-black text-white italic leading-none mb-3 tracking-tighter">{stat.value}</div>
                  <div className="text-[10px] font-black uppercase tracking-widest text-slate-500 group-hover:text-slate-300 transition-colors">{stat.label}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
    );
};

export default WhatsAppSection;
