import React, { useState } from 'react';
import Icon from '../../../components/AppIcon';

const FAQSection = ({ data }) => {
  const [openIndex, setOpenIndex] = useState(null);

  const faqs = data?.items || [
    {
      id: 1,
      category: "General",
      question: "What is LUC Opportunities and how does it work?",
      answer: "LUC Opportunities is a community-driven platform that curates and shares educational and career opportunities from around the world."
    }
  ];

  const categories = ["All", ...new Set(faqs.map(faq => faq.category))];
  const [selectedCategory, setSelectedCategory] = useState("All");

  const filteredFAQs = selectedCategory === "All"
    ? faqs
    : faqs?.filter(faq => faq?.category === selectedCategory);

  const toggleFAQ = (index) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  return (
    <section id="faq" className="py-12 md:py-16 lg:py-20 bg-[var(--color-background)]">
      <div className="max-w-4xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-8 md:mb-12">
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-4 md:mb-6" style={{ fontFamily: 'var(--font-headline)' }}>
            {data?.title || "Frequently Asked Questions"}
          </h2>
          <p className="text-base md:text-lg text-[var(--color-muted-foreground)] max-w-2xl mx-auto">
            {data?.description || "Find quick answers to common questions about LUC Opportunities."}
          </p>
        </div>

        <div className="flex flex-wrap gap-2 md:gap-3 mb-8 md:mb-12 justify-center">
          {categories?.map((category) => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              className={`px-4 py-2 rounded-lg text-sm md:text-base font-medium transition-all duration-300 ${selectedCategory === category
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-[var(--color-muted)] text-[var(--color-foreground)] hover:bg-[var(--color-primary)]/10'
                }`}
              style={{ fontFamily: 'var(--font-cta)' }}
            >
              {category}
            </button>
          ))}
        </div>

        <div className="space-y-4 md:space-y-6">
          {filteredFAQs?.map((faq, index) => (
            <div
              key={faq?.id || index}
              className="bg-[var(--color-card)] rounded-xl shadow-[var(--shadow-card)] border border-[var(--color-border)] overflow-hidden transition-all duration-300"
            >
              <button
                onClick={() => toggleFAQ(index)}
                className="w-full px-4 md:px-6 py-4 md:py-5 flex items-center justify-between gap-4 text-left hover:bg-[var(--color-muted)]/50 transition-colors duration-300"
              >
                <div className="flex-1 min-w-0">
                  <span className="inline-block px-2 py-1 rounded text-xs font-medium bg-[var(--color-brand-blue)]/10 text-[var(--color-brand-blue)] mb-2">
                    {faq?.category}
                  </span>
                  <h3 className="text-base md:text-lg font-semibold text-[var(--color-primary)]" style={{ fontFamily: 'var(--font-headline)' }}>
                    {faq?.question}
                  </h3>
                </div>
                <Icon
                  name={openIndex === index ? "ChevronUp" : "ChevronDown"}
                  size={20}
                  className="flex-shrink-0 transition-transform duration-300"
                />
              </button>

              <div
                className={`overflow-hidden transition-all duration-300 ${openIndex === index ? 'max-h-96' : 'max-h-0'
                  }`}
              >
                <div className="px-4 md:px-6 pb-4 md:pb-5">
                  <p className="text-sm md:text-base text-[var(--color-muted-foreground)] leading-relaxed">
                    {faq?.answer}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-8 md:mt-12 text-center p-6 md:p-8 bg-[var(--color-card)] rounded-2xl shadow-[var(--shadow-card)] border border-[var(--color-border)]">
          <Icon name="HelpCircle" size={32} color="var(--color-brand-blue)" className="mx-auto mb-4 md:mb-6" />
          <h3 className="text-lg md:text-xl font-semibold text-[var(--color-primary)] mb-3 md:mb-4" style={{ fontFamily: 'var(--font-headline)' }}>
            Still Have Questions?
          </h3>
          <p className="text-sm md:text-base text-[var(--color-muted-foreground)] mb-4 md:mb-6">
            Can't find the answer you're looking for? Our community support team is here to help.
          </p>
          <div className="flex flex-col sm:flex-row gap-3 md:gap-4 justify-center">
            <a
              href="#contact-form"
              className="inline-flex items-center justify-center gap-2 px-6 py-3 rounded-lg bg-primary text-primary-foreground font-semibold hover:opacity-90 transition-opacity duration-300 text-sm md:text-base shadow-sm"
              style={{ fontFamily: 'var(--font-cta)' }}
            >
              <Icon name="MessageCircle" size={20} />
              Ask a Question
            </a>
            <a
              href="mailto:hello@lucopportunities.com"
              className="inline-flex items-center justify-center gap-2 px-6 py-3 rounded-lg border-2 border-primary text-primary font-semibold hover:bg-muted/10 transition-colors duration-300 text-sm md:text-base"
              style={{ fontFamily: 'var(--font-cta)' }}
            >
              <Icon name="Mail" size={20} />
              Email Us
            </a>
          </div>
        </div>
      </div>
    </section>
  );
};

export default FAQSection;